def apply_top_only_rule(grid):
    from collections import deque
    output = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 3 and (r,c) not in visited:
                comp = []
                queue = deque([(r,c)])
                visited.add((r,c))
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 3 and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                queue.append((nr,nc))

                if len(comp) <= 1:
                    continue

                max_col = max(cc for a,b in comp)
                top_row = min(a for a,b in comp)
                top_right_col = max(b for a,b in comp if a == top_row)
                if top_right_col != max_col:
                    continue

                # Keep top pixel, change all others to 0
                top_pixel = min(comp, key=lambda x: (x[0], x[1]))
                for pixel in comp:
                    if pixel != top_pixel:
                        output[pixel[0]][pixel[1]] = 0

    return output

